declare(strict_types=1);
function install_schema(PDO $pdo): void {
 $pdo->exec("CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS articles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL UNIQUE, category VARCHAR(100) NOT NULL DEFAULT 'Training', excerpt TEXT NOT NULL, body MEDIUMTEXT NOT NULL, image_url VARCHAR(500) NOT NULL DEFAULT '', author VARCHAR(120) NOT NULL DEFAULT 'Fitzeno Team', published TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(published,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, category VARCHAR(100) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, image_url VARCHAR(500) NOT NULL DEFAULT '', badge VARCHAR(60) NOT NULL DEFAULT '', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(active,category)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS classes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, slug VARCHAR(170) NOT NULL UNIQUE, category VARCHAR(80) NOT NULL, description TEXT NOT NULL, duration VARCHAR(40) NOT NULL DEFAULT '45 min', level VARCHAR(50) NOT NULL DEFAULT 'All levels', image_url VARCHAR(500) NOT NULL DEFAULT '', active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS clubs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, address VARCHAR(220) NOT NULL, description TEXT NOT NULL, image_url VARCHAR(500) NOT NULL DEFAULT '', hours VARCHAR(120) NOT NULL DEFAULT 'Every day · 6:00 am – 10:00 pm', membership VARCHAR(180) NOT NULL DEFAULT 'Flexible options · Ask our team', active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS leads (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(50) NOT NULL, interest VARCHAR(150) NOT NULL DEFAULT '', message TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'New', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $count=(int)$pdo->query('SELECT COUNT(*) FROM settings')->fetchColumn();
 if($count===0){ $seed=['brand_name'=>'FITZENO','tagline'=>'Move with purpose. Live with energy.','phone'=>'+94 11 234 5678','email'=>'hello@fitzeno.space','address'=>'Colombo 03, Sri Lanka','instagram'=>'https://instagram.com/','facebook'=>'https://facebook.com/','hero_title'=>'MAKE YOUR<br>MOVE.','hero_kicker'=>'COLOMBO · KANDY · GALLE','hero_image'=>'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=2200&q=88','announcement'=>'YOUR STRONGEST CHAPTER STARTS HERE','install_complete'=>'1']; $stmt=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?)'); foreach($seed as $key=>$value)$stmt->execute([$key,$value]); }
 $articles=[
 ['Strength, Sri Lankan style: build a routine that lasts','strength-sri-lankan-style','Training','A practical guide to building strength around real life, local food and a schedule you can sustain.','Progress is built in the ordinary moments: the session you show up for after work, the extra repetition you earn with good form, and the meal that helps you recover. Start with two full-body sessions each week. Learn the squat, hinge, push and pull. Add load gradually, and leave a little energy in reserve.\n\nSri Lankan staples can support a strong training routine. Build meals around rice or manioc, dhal, eggs, fish, chicken, leafy greens and seasonal fruit. Hydration matters in our warm climate: keep water close, especially on long training days.\n\nYour first plan does not need to be complicated. Choose a time, make it repeatable, and let consistency do the heavy lifting.'],
 ['Colombo after work: your 45-minute reset','colombo-after-work-reset','Lifestyle','A focused training session can turn the journey home into the best part of your day.','When the Colombo workday runs long, a short, clear plan makes it easier to keep your promise to yourself. Walk in with one intention: move well for 45 minutes. A warm-up, three purposeful strength movements and a few minutes of conditioning can be enough.\n\nPack your kit in the morning and pick a class or training window before the calendar fills. Leave room for traffic, and keep a second time option in your week. The best routine is the one that survives a busy Tuesday.\n\nFinish with a calm cool-down, water and a meal that feels familiar. Training should give energy back to your life.'],
 ['A beginner’s guide to strength training','beginners-guide-to-strength','Training','Start with the fundamentals, build confidence and make every repetition count.','Strength training is for every body and every starting point. Your first goal is to learn a few foundational movement patterns with control. A coach can help you find a comfortable range, set up equipment and choose a load that lets you move confidently.\n\nBegin with two or three sessions per week and give yourself a rest day between harder workouts. Add repetitions before adding weight. Stop a set when your form changes, and ask questions whenever something feels unfamiliar.\n\nSmall progress is still progress. Keep a simple note of what you did, celebrate a steadier movement or an extra repetition, and let confidence grow alongside strength.'],
 ['Recovery is part of the plan','recovery-is-part-of-the-plan','Recovery','Sleep, hydration and lighter days help your training settle into lasting progress.','Training is a stimulus. Recovery is when your body adapts. Sleep, nourishing meals and manageable stress all influence how ready you feel for the next session. You do not need a perfect routine; start with a consistent bedtime and a bottle of water within reach.\n\nAlternate demanding sessions with easier movement. A walk along Galle Face, a gentle mobility class or an unhurried stretch can keep you active while letting tired muscles recover.\n\nPay attention to patterns over time. Persistent pain, unusual fatigue or a change in health is a reason to pause and speak with a qualified health professional.'],
 ['Move together: why group classes work','move-together-group-classes','Community','Find your rhythm with coaching, music and a room full of shared energy.','A group class gives your week a meeting point. The instructor sets the pace, offers options and makes it easier to focus on the movement in front of you. From rhythm-led cycling to controlled Pilates, there is a format for different moods and goals.\n\nIf you are new, arrive a few minutes early and tell the coach. You can take a lower-impact option, rest when needed and build intensity at your own pace. The room is there for you, not the other way around.\n\nBring a friend, learn names and enjoy the shared momentum. A little community can make a good habit feel natural.'],
 ['Training through the tropical heat','training-through-tropical-heat','Wellbeing','Simple ways to plan comfortable sessions in Sri Lanka’s warm, humid climate.','Warm weather asks for a little more planning. Choose breathable kit, arrive hydrated and ease into the first few minutes instead of rushing straight into hard work. If you have spent the day outdoors, give yourself time to cool down before training.\n\nDrink to thirst and take water breaks. Classes and personal training can be adjusted when the day feels especially humid. There is no benefit in pushing through dizziness, nausea or feeling faint: stop, move to a cool place and tell a member of staff.\n\nListen to your body, keep the effort appropriate and make consistency the goal. Your coach can help you adjust a session for the conditions.']
 ];
